// Conversion of date fields from ragflow databases

return items.map(item => {

  const data = item.json;

  // Función para formatear la fecha
  function formatToSupabase(dateString) {
    if (!dateString || typeof dateString !== 'string') {
      return null; // O devuelve el valor original
    }

    const dateObject = new Date(dateString);

    // 1. Obtenemos el string ISO (ej: 2025-10-22T23:32:44.000Z)
    const isoString = dateObject.toISOString();

    // 2. Quitamos la 'Z' del final
    //    (Resultado: "2025-10-22T23:32:44.000")
    const withoutZ = isoString.slice(0, -1);

    // 3. Añadimos los 3 ceros extra (microsegundos) y el "+00:00"
    //    (Resultado: "2025-10-22T23:32:44.000000+00:00")
    return withoutZ + "000+00:00";
  }

  // --- create_date conversion ---
  data.create_date = formatToSupabase(data.create_date);

  // --- update_date conversion ---
  data.update_date = formatToSupabase(data.update_date);

  // Output
  return item;
});

