// 'items' es el array de entrada (que contiene 1 item con toda la respuesta)
// 1. Accedemos al primer y único item que viene del nodo If
const inputData = items[0].json;

// 2. Navegamos dentro del JSON para encontrar el array 'docs'
// inputData.data -> { "docs": [...] }
const documentList = inputData.data.docs;

// 3. Función de ayuda para convertir fechas (la que hicimos antes)
function formatToSupabase(dateString) {
  if (!dateString || typeof dateString !== 'string') {
    return null; // Devuelve null si la fecha no existe
  }
  const dateObject = new Date(dateString);
  const isoString = dateObject.toISOString();
  // Convierte "2025-10-22T23:33:08.000Z" a "2025-10-22T23:33:08.000000+00:00"
  const withoutZ = isoString.slice(0, -1);
  return withoutZ + "000+00:00";
}

// 4. Usamos .map() para transformar la lista de documentos
//    en una nueva lista de items para n8n.
const outputItems = documentList.map(doc => {

  // Creamos el nuevo objeto JSON que SÍ coincide
  // con el esquema de tu tabla 'document'
  const formattedDocument = {
    id: doc.id,
    create_date: formatToSupabase(doc.create_date),
    update_date: formatToSupabase(doc.update_date),
    thumbnail: doc.thumbnail,
    kb_id: doc.dataset_id, // RENOMBRADO
    parser_id: doc.chunk_method, // RENOMBRADO
    parser_config: JSON.stringify(doc.parser_config), // CONVERTIDO A STRING
    source_type: doc.source_type,
    type: doc.type,
    created_by: doc.created_by,
    name: doc.name,
    location: doc.location,
    size: doc.size,
    token_num: doc.token_count, // RENOMBRADO
    chunk_num: doc.chunk_count, // RENOMBRADO
    progress: doc.progress,
    progress_msg: doc.progress_msg,
    process_begin_at: formatToSupabase(doc.process_begin_at), // CONVERTIDO
    process_duration: doc.process_duration,
    meta_fields: JSON.stringify(doc.meta_fields), // CONVERTIDO A STRING
    suffix: doc.suffix,
    run: doc.run,
    status: doc.status
  };

  return {
    json: formattedDocument
  };
});

// 5. Devolvemos la nueva lista de items.
// El siguiente nodo (ej. 'Supabase Insert') recibirá
// 12 items (en tu ejemplo), cada uno con el formato
// perfecto para la tabla 'document'.
return outputItems;

